(4493845, 647042, 80908, '<td valign="top">Beautifully lit, great expression by the model. Very moody, its all good. Downside? The catchlight obscuring part of the eye. Minor point though!</td>', 'Beautifully lit, great expression by the model. Very moody, its all good. Downside? The catchlight obscuring part of the eye. Minor point though!', '2008-02-18 05:05:29.000000', NULL, 1),
(4493846, 647185, 80908, '<td valign="top">I was going to comment on the unfortunate shadow, but then I got the point! Nicely done, although I am not sure that it needed the fisheye effect.</td>', 'I was going to comment on the unfortunate shadow, but then I got the point! Nicely done, although I am not sure that it needed the fisheye effect.', '2008-02-18 05:06:43.000000', NULL, 1),
