(4493850, 647903, 80908, '<td valign="top">Great idea and composition, but needs a bit more contrast on the right hand side, and the model needs to keep her hand more still (or use a faster exposure and some lighting for the bum!)</td>', 'Great idea and composition, but needs a bit more contrast on the right hand side, and the model needs to keep her hand more still (or use a faster exposure and some lighting for the bum!)', '2008-02-18 05:09:59.000000', NULL, 1),
(4493851, 647929, 80908, '<td valign="top">Great idea, but several issues with the lighting - the box looks overexposed and the blade underexposed. There is also a lot of noise - was this a high ISO?</td>', 'Great idea, but several issues with the lighting - the box looks overexposed and the blade underexposed. There is also a lot of noise - was this a high ISO?', '2008-02-18 05:12:10.000000', NULL, 1),
(4493852, 648088, 80908, '<td valign="top">They''re free, but you''ll have to explain this one to me! I don''t see a photo? Ah - got it... looks overexposed though. :o)</td>', 'They''re free, but you''ll have to explain this one to me! I don''t see a photo? Ah - got it... looks overexposed though. :o)', '2008-02-18 05:13:29.000000', NULL, 1),
