(4508647, 648088, 83313, '<td valign="top">Ok, someone had to do it... A 6 for having the sheer cajones (or chutzpah, depending on where you are from) to enter this.</td>', 'Ok, someone had to do it... A 6 for having the sheer cajones (or chutzpah, depending on where you are from) to enter this.', '2008-02-22 22:22:07.000000', NULL, 1),
