INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4521303, 647138, 52750, '<td valign="top">It fits the category if you look at it like the submission itself was a misunderstanding.<br/> <br/>I like the scene, but thought it looked somewhat over processed.</td>', 'It fits the category if you look at it like the submission itself was a misunderstanding. I like the scene, but thought it looked somewhat over processed.', '2008-02-27 10:25:36.000000', NULL, 0),
(4522166, 648091, 67697, '<td valign="top">I love the inclusion of the geese.  This is such a pretty photo.  I love that blue and the moon looks so cool.  Actually it looks cold, with the clouds looking like they are wisping off of it - like a mountain peak.</td>', 'I love the inclusion of the geese.  This is such a pretty photo.  I love that blue and the moon looks so cool.  Actually it looks cold, with the clouds looking like they are wisping off of it - like a mountain peak.', '2008-02-27 13:29:33.000000', NULL, 0),
(4522664, 647812, 30049, '<td valign="top">Greetings from the Critique Club<br/> <br/><u>First Impression(s)</u> <br/> <br/>Yellow, hazy, harsh...why''s he walking away?<br/> <br/><u>Looking Deeper</u> <br/> <br/>This was a tough challenge, both for the submitter and the viewer/voter.  The challenge theme/description left a lot out there for interpretation.  To communicate the concept of ''Misunderstanding'' in a photo without a long, wordy title was difficult.<br/> <br/>Your photo tells a story, or at least part of a story.  The man in the photo, or the observer watching, could be ''Misunderstood''.  He''s traveling the train tracks.  Does this mean he''s a drifter; homeless perhaps?  Even the back of the sign leaves a question mark; what does it say?<br/> <br/>The conditions and presentation in your image work well with this story.  The glaring sun, the desolate surroundings.<br/> <br/>Compositionally the tracks present a nice set of leading lines, complemented by the overhead wires going the same direction.  I''d had liked less sky, but then it throws the man more into the center...  The coloration of the sky is a little strange also...almost a peachy color.  Why not white or grey?<br/> <br/>In the end I think this image required too much thinking for the average "click and keep on going" voter.  Missing the eye-candy, fun, clean &amp; simple approach probably took away some scoring potential - but it is an engaging photo nonetheless.<br/> <br/>Questions?  Feel free to send me a PM for any clarification.  Thanks!</td>', 'Greetings from the Critique Club First Impression(s)  Yellow, hazy, harsh...why''s he walking away? Looking Deeper  This was a tough challenge, both for the submitter and the viewer/voter.  The challenge theme/description left a lot out there for interpretation.  To communicate the concept of ''Misunderstanding'' in a photo without a long, wordy title was difficult. Your photo tells a story, or at least part of a story.  The man in the photo, or the observer watching, could be ''Misunderstood''.  He''s traveling the train tracks.  Does this mean he''s a drifter; homeless perhaps?  Even the back of the sign leaves a question mark; what does it say? The conditions and presentation in your image work well with this story.  The glaring sun, the desolate surroundings. Compositionally the tracks present a nice set of leading lines, complemented by the overhead wires going the same direction.  I''d had liked less sky, but then it throws the man more into the center...  The coloration of the sky is a little strange also...almost a peachy color.  Why not white or grey? In the end I think this image required too much thinking for the average "click and keep on going" voter.  Missing the eye-candy, fun, clean & simple approach probably took away some scoring potential - but it is an engaging photo nonetheless. Questions?  Feel free to send me a PM for any clarification.  Thanks!', '2008-02-27 16:29:53.000000', NULL, 0),
(4524594, 648090, 30049, '<td valign="top">Greetings from the Critique Club<br/> <br/><u>First Impression</u> <br/> <br/>Nasty, gross, YUCK!  Then funny.  :-)<br/> <br/><u>Looking Deeper</u> <br/> <br/>As a parent I connected immediately to the photo and the humor - after I got past the gross part (I guess being a parent helped with that too).<br/> <br/>The concept fit the challenge quite well IMO, and I think many of the commenters recognized the connection as well.  Could be why roughly 10% of the voters commented, and they scored it 1.5pts above the end average.<br/> <br/>So what happened?  I think either a number of people didn''t get it and voted it low, however I think maybe a larger number were just plain grossed out by it and gave it a low score.<br/> <br/>Kind of shows how subject matter can be a factor in how well or poorly an image does in challenges here.  I could be wrong (often am).  :-)  <br/> <br/>Outside of subject I don''t see that much out of place on technical grounds that would drag the score down on this photo.  There''s a little bit of glare from the flash (tongue &amp; peanut butter), but barely.  The photo does seem just a tad dark, but yet the white of the diapers seem about right exposure wise.  Compositionally I think you placed the objects correctly with a nice triangle formed between the hand, diapers, and face.  One consideration...the border adds to the dark feel of the image and blends in with the darker areas.  A border with a single black pixel, then white, (or vice-versa) would be interesting to try (to see any difference in overall feel).<br/> <br/>Hopefully I''m not way off base, and this has been helpful in some manner for you.  If you have any questions, or would like clarification, please feel free to send me a PM.  Thanks.</td>', 'Greetings from the Critique Club First Impression  Nasty, gross, YUCK!  Then funny.  :-) Looking Deeper  As a parent I connected immediately to the photo and the humor - after I got past the gross part (I guess being a parent helped with that too). The concept fit the challenge quite well IMO, and I think many of the commenters recognized the connection as well.  Could be why roughly 10% of the voters commented, and they scored it 1.5pts above the end average. So what happened?  I think either a number of people didn''t get it and voted it low, however I think maybe a larger number were just plain grossed out by it and gave it a low score. Kind of shows how subject matter can be a factor in how well or poorly an image does in challenges here.  I could be wrong (often am).  :-)   Outside of subject I don''t see that much out of place on technical grounds that would drag the score down on this photo.  There''s a little bit of glare from the flash (tongue & peanut butter), but barely.  The photo does seem just a tad dark, but yet the white of the diapers seem about right exposure wise.  Compositionally I think you placed the objects correctly with a nice triangle formed between the hand, diapers, and face.  One consideration...the border adds to the dark feel of the image and blends in with the darker areas.  A border with a single black pixel, then white, (or vice-versa) would be interesting to try (to see any difference in overall feel). Hopefully I''m not way off base, and this has been helpful in some manner for you.  If you have any questions, or would like clarification, please feel free to send me a PM.  Thanks.', '2008-02-28 09:18:48.000000', NULL, 0),
(4525032, 648066, 90866, '<td valign="top">Totally cool photo. Congrads.</td>', 'Totally cool photo. Congrads.', '2008-02-28 11:22:55.000000', NULL, 0),
